Lemma unreg_iter_head : forall (A K beg srz : Z) (w1 w3 w4 w5 w6 w7 : word)
    (ra gp tp t0 t1 t2 s0 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (sp : word) F fc (m : mem),
  ro_cells asegs m A [C8 (Z_to_bv 64 beg); C8 w1; C8 (Z_to_bv 64 srz); C8 w3; C8 w4; C8 w5; C8 w6; C8 w7] ->
  rw_cells asegs m 0x231018 [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x22fb9c [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x22db50 [C4 (Z_to_bv 64 1)] ->
  ro_cells asegs m 0x230338 [C8 (Z_to_bv 64 0x7fff8000)] ->
  ro_cells asegs m 0x2c1ee0 [C8 (Z_to_bv 64 0xffffffffffffffff)] ->
  ro_cells asegs m 0x213938 [C8 (Z_to_bv 64 0x203df0)] ->
  stk asegs m XS1_LO XS1_HI -> stk asegs m XS2_LO XS2_HI -> stk asegs m XS3_LO XS3_HI ->
  ((XS1_LO <= SHB + beg / 8 /\ SHB + beg / 8 + srz / 8 <= XS1_HI)
   \/ (XS2_LO <= SHB + beg / 8 /\ SHB + beg / 8 + srz / 8 <= XS2_HI)
   \/ (XS3_LO <= SHB + beg / 8 /\ SHB + beg / 8 + srz / 8 <= XS3_HI)) ->
  0 <= beg -> beg mod 8 = 0 -> 8 <= srz -> srz mod 8 = 0 -> beg + srz <= 0x785000 -> srz / 8 < 0x10000 ->
  0x216510 <= A -> A + 64 <= 0x22cc50 -> 1 <= K <= 1437 ->
  mem_inv asegs m ->
  evt asegs (fun ms' => exists (s0' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem),
        ms' = MS (mkR (Z_to_bv 64 0xaf808) sp gp tp t0' t1' t2' s0' (Z_to_bv 64 0x2c1e68) a0' a1' a2' a3' a4' a5' a6' a7'
                      (Z_to_bv 64 2) (Z_to_bv 64 0x254cb) (Z_to_bv 64 A) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x22dbb0)
                      (Z_to_bv 64 0x213938) (Z_to_bv 64 0x22dbf0) (Z_to_bv 64 0x22db38) (Z_to_bv 64 0x230338) (Z_to_bv 64 K)
                      t3' t4' t5' t6')
                 F (Z_to_bv 64 0xaf808) fc None m' (seg_rom asegs)
        /\ munch [(XS1_LO, XS1_HI); (XS2_LO, XS2_HI); (XS3_LO, XS3_HI)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
        /\ stk asegs m' XS1_LO XS1_HI /\ stk asegs m' XS2_LO XS2_HI /\ stk asegs m' XS3_LO XS3_HI)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 0x2c1e68) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 2) (Z_to_bv 64 0x254cb) (Z_to_bv 64 A) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x22dbb0)
             (Z_to_bv 64 0x213938) (Z_to_bv 64 0x22dbf0) (Z_to_bv 64 0x22db38) (Z_to_bv 64 0x230338) (Z_to_bv 64 K)
             t3 t4 t5 t6)
        F (Z_to_bv 64 0xaf820) fc None m (seg_rom asegs)).
Proof.
