  ro_cells asegs m A [C8 w0; C8 w1; C8 w2; C8 w3; C8 w4; C8 w5; C8 w6; C8 (Z_to_bv 64 odr)] ->
  rw_cells asegs m 0x762a20 [C1 o1] -> rw_cells asegs m 0x7629c0 [C1 o2] -> rw_cells asegs m 0x7629c1 [C1 o3] -> rw_cells asegs m 0x762a21 [C1 o4] -> rw_cells asegs m 0x762a22 [C1 o5] ->
  (odr = ODR_NONE \/ odr = 0x762a20 \/ odr = 0x7629c0 \/ odr = 0x7629c1 \/ odr = 0x762a21 \/ odr = 0x762a22) ->
  0x216510 <= A -> A + 64 <= 0x22cc50 -> 1 <= K <= 1437 ->
  mem_inv asegs m ->
  evt asegs (fun ms' => exists (ra' s0' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem) (o1' o2' o3' o4' o5' : byte),
        ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0' (Z_to_bv 64 0x2c1e68) a0' a1' a2' a3' a4' a5' a6' a7'
                      (Z_to_bv 64 2) (Z_to_bv 64 0x254cb) (Z_to_bv 64 (A + 64)) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x22dbb0)
                      (Z_to_bv 64 0x213938) (Z_to_bv 64 0x22dbf0) (Z_to_bv 64 0x22db38) (Z_to_bv 64 0x230338) (Z_to_bv 64 (K - 1))
                      t3' t4' t5' t6')
                 F (Z_to_bv 64 (if K =? 1 then 0xafa24 else 0xaf820)) fc None m' (seg_rom asegs)
        /\ munch [(0x762a20, 0x762a23); (0x7629c0, 0x7629c2)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
        /\ rw_cells asegs m' 0x762a20 [C1 o1'] /\ rw_cells asegs m' 0x7629c0 [C1 o2'] /\ rw_cells asegs m' 0x7629c1 [C1 o3'] /\ rw_cells asegs m' 0x762a21 [C1 o4'] /\ rw_cells asegs m' 0x762a22 [C1 o5'])
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 0x2c1e68) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 2) (Z_to_bv 64 0x254cb) (Z_to_bv 64 A) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x22dbb0)
             (Z_to_bv 64 0x213938) (Z_to_bv 64 0x22dbf0) (Z_to_bv 64 0x22db38) (Z_to_bv 64 0x230338) (Z_to_bv 64 K)
             t3 t4 t5 t6)
        F (Z_to_bv 64 0xaf808) fc None m (seg_rom asegs)).
